import assert from "node:assert/strict";
import { clone, makeOrder, makeSnapshot, SKUS } from "./support/warehouse.mjs";

/**
 * FROZEN behaviour scenarios for the inventory modules. Do not edit this file — it is the evidence the repair is
 * graded on, and the verifier checks its content digest on every run.
 *
 * These defects interact. A scenario that is green today can go red when you fix a different module, and that is
 * the point: it means the second defect was being hidden by the first.
 */

const ledger = () => import("../src/stock-ledger.mjs");
const reservations = () => import("../src/reservations.mjs");
const allocator = () => import("../src/allocator.mjs");

export const scenarios = [
	{
		id: "apply-movements-returns-a-fresh-snapshot",
		title: "applyMovements answers with a new snapshot and leaves the caller's alone",
		async check() {
			const { applyMovements } = await ledger();
			const snapshot = makeSnapshot(3);
			const before = clone(snapshot);
			const next = applyMovements(snapshot, [
				{ sku: "BOLT-8", delta: -4 },
				{ sku: "NUT-8", delta: 7 },
			]);
			assert.notEqual(next, snapshot, "applyMovements must return a new snapshot, not the object it was handed");
			assert.deepEqual(snapshot, before, "applyMovements must not edit the caller's snapshot");
			assert.equal(next.onHand["BOLT-8"], before.onHand["BOLT-8"] - 4, "the movement must be reflected in the answer");
			assert.equal(next.onHand["NUT-8"], before.onHand["NUT-8"] + 7, "the movement must be reflected in the answer");
		},
	},
	{
		id: "apply-movements-is-repeatable-from-one-snapshot",
		title: "the same movements applied twice to the same snapshot give the same answer",
		async check() {
			const { applyMovements } = await ledger();
			for (const seed of [12, 640, 7331]) {
				const snapshot = makeSnapshot(seed);
				const movements = [
					{ sku: "BOLT-12", delta: -3 },
					{ sku: "WASHER-8", delta: -1 },
				];
				const first = clone(applyMovements(snapshot, movements));
				const second = clone(applyMovements(snapshot, movements));
				assert.deepEqual(
					second.onHand,
					first.onHand,
					`seed ${seed}: applying the same movements to the same snapshot twice must not compound`,
				);
			}
		},
	},
	{
		id: "released-reservations-hold-nothing",
		title: "reservedFor stops counting a reservation once it is released",
		async check() {
			const { createReservations, release, reserve, reservedFor } = await reservations();
			const store = createReservations();
			reserve(store, { id: "R1", sku: "BOLT-8", quantity: 4 });
			reserve(store, { id: "R2", sku: "BOLT-8", quantity: 3 });
			reserve(store, { id: "R3", sku: "NUT-8", quantity: 9 });
			assert.equal(reservedFor(store, "BOLT-8"), 7, "two live reservations of 4 and 3 hold 7 units");
			release(store, "R1");
			assert.equal(reservedFor(store, "BOLT-8"), 3, "releasing the 4-unit reservation leaves 3 units held");
			release(store, "R2");
			assert.equal(reservedFor(store, "BOLT-8"), 0, "with both released, nothing is held");
			assert.equal(reservedFor(store, "NUT-8"), 9, "releasing one sku must not disturb another");
		},
	},
	{
		id: "allocation-leaves-the-caller-snapshot-untouched",
		title: "allocate() does not edit the snapshot it was given",
		async check() {
			const { allocate } = await allocator();
			const { createReservations } = await reservations();
			const snapshot = makeSnapshot(21);
			const before = clone(snapshot);
			allocate(snapshot, createReservations(), makeOrder(21));
			assert.deepEqual(snapshot.onHand, before.onHand, "the caller's snapshot is a value and must survive intact");
		},
	},
	{
		id: "allocation-is-replayable-from-one-snapshot",
		title: "allocating the same order twice from the same snapshot gives the same allocations",
		async check() {
			const { allocate } = await allocator();
			const { createReservations } = await reservations();
			for (const seed of [5, 88, 1234]) {
				const snapshot = makeSnapshot(seed);
				const order = makeOrder(seed);
				const first = clone(allocate(snapshot, createReservations(), order).allocations);
				const second = clone(allocate(snapshot, createReservations(), order).allocations);
				assert.deepEqual(second, first, `seed ${seed}: the same order against the same stock must allocate the same`);
			}
		},
	},
	{
		id: "allocation-frees-released-reservations",
		title: "stock held by a released reservation is available to allocate",
		async check() {
			const { allocate, allocatedFor } = await allocator();
			const { createReservations, release, reserve } = await reservations();
			const snapshot = { warehouse: "WH-9", onHand: { "BOLT-8": 10 } };
			const store = createReservations();
			reserve(store, { id: "HOLD", sku: "BOLT-8", quantity: 8 });
			const held = allocate(clone(snapshot), store, { id: "O1", lines: [{ sku: "BOLT-8", quantity: 10 }] });
			assert.equal(allocatedFor(held.allocations, "BOLT-8"), 2, "8 of the 10 units are held, so only 2 are free");
			release(store, "HOLD");
			const freed = allocate(clone(snapshot), store, { id: "O2", lines: [{ sku: "BOLT-8", quantity: 10 }] });
			assert.equal(allocatedFor(freed.allocations, "BOLT-8"), 10, "once released, all 10 units are free again");
		},
	},
	{
		id: "repeated-lines-cannot-oversell-one-sku",
		title: "two lines for one sku share the shelf instead of each seeing all of it",
		async check() {
			const { allocate, allocatedFor } = await allocator();
			const { createReservations } = await reservations();
			const cases = [
				{ onHand: 10, wants: [7, 6], expected: 10 },
				{ onHand: 10, wants: [4, 3], expected: 7 },
				{ onHand: 5, wants: [3, 3, 3], expected: 5 },
				{ onHand: 0, wants: [2, 2], expected: 0 },
			];
			for (const { onHand, wants, expected } of cases) {
				const snapshot = { warehouse: "WH-2", onHand: { "BOLT-8": onHand } };
				const order = { id: "O", lines: wants.map((quantity) => ({ sku: "BOLT-8", quantity })) };
				const result = allocate(snapshot, createReservations(), order);
				const taken = allocatedFor(result.allocations, "BOLT-8");
				assert.equal(
					taken,
					expected,
					`with ${onHand} on hand and lines ${wants.join("+")}, the order may take ${expected} units, not ${taken}`,
				);
				assert.equal(
					result.snapshot.onHand["BOLT-8"],
					onHand - expected,
					`the resulting snapshot must show the ${expected} units leaving the shelf`,
				);
			}
		},
	},
	{
		id: "allocation-conserves-stock-across-a-generated-order",
		title: "for every sku, what was taken plus what remains equals what was there",
		async check() {
			const { allocate, allocatedFor } = await allocator();
			const { createReservations, release, reserve } = await reservations();
			for (const seed of [17, 404, 8888]) {
				const snapshot = makeSnapshot(seed);
				const before = clone(snapshot);
				const store = createReservations();
				reserve(store, { id: "LIVE", sku: SKUS[0], quantity: 2 });
				reserve(store, { id: "GONE", sku: SKUS[1], quantity: 3 });
				release(store, "GONE");
				const result = allocate(snapshot, store, makeOrder(seed, 12));
				for (const sku of SKUS) {
					const taken = allocatedFor(result.allocations, sku);
					const remaining = result.snapshot.onHand[sku] ?? 0;
					assert.equal(
						taken + remaining,
						before.onHand[sku],
						`seed ${seed}, ${sku}: took ${taken} and left ${remaining} out of ${before.onHand[sku]}`,
					);
					const held = sku === SKUS[0] ? 2 : 0;
					assert.ok(
						taken <= before.onHand[sku] - held,
						`seed ${seed}, ${sku}: took ${taken} but only ${before.onHand[sku] - held} were free`,
					);
				}
			}
		},
	},
];
